-- Esquema de Luciérnaga en PostgreSQL (Supabase).
--
-- Generado por backend/scripts/migracion/generar-esquema-pg.cjs a partir del
-- esquema real de MySQL, no de database/schema.sql, que ya no refleja lo que
-- hay en la base.
--
-- Diferencias respecto a MySQL, todas deliberadas:
--
--   * AUTO_INCREMENT pasa a GENERATED BY DEFAULT AS IDENTITY, que admite que la
--     migración inserte los ids existentes. Al final se recolocan las secuencias.
--   * ON UPDATE CURRENT_TIMESTAMP no existe en PostgreSQL: se sustituye por el
--     trigger `tocar_updated_at`, definido abajo una sola vez.
--   * Los enum de MySQL pasan a varchar con un CHECK: un enum de PostgreSQL es
--     un tipo propio y obligaría a migrarlo aparte sin ganar nada aquí.
--   * Las columnas de `inventario` van entre comillas porque están en
--     mayúsculas; sin comillas, PostgreSQL las pasaría a minúsculas.
--
-- Idempotente: se puede ejecutar varias veces.
--
-- El perfil CALIDAD se retiró del software: sus tablas (`asignacion_caja_calidad`,
-- `asignacion_calidad`, `modulo_calidad`) ya no se crean. En una base que las
-- tenga, `04-sin-calidad.sql` las retira.


CREATE TABLE IF NOT EXISTS asignacion_caja_tecnica (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  modulo_id integer NOT NULL,
  usuario_id integer NOT NULL,
  upd_inicio varchar(10),
  ultimo_upd varchar(10),
  PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS asignacion_caja_tecnica_modulo_id ON asignacion_caja_tecnica (modulo_id);
CREATE INDEX IF NOT EXISTS asignacion_caja_tecnica_usuario_id ON asignacion_caja_tecnica (usuario_id);

-- Cierre de jornada declarado por quien digita: "esta caja la terminé" o "la
-- sigo mañana". Lo demás de una jornada (cuántos registros, a qué hora, con qué
-- UPD) se deduce de fuiddatosreal; la intención no se puede deducir, y es lo
-- que permite dar por cerrada la producción de un día aunque la caja siga
-- abierta al siguiente. Una fila por caja, día y persona.
CREATE TABLE IF NOT EXISTS jornada_caja (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  caja_modulo varchar(255) NOT NULL,
  fecha date NOT NULL,
  colaborador varchar(255) NOT NULL,
  resultado varchar(20) NOT NULL,
  usuario_id integer,
  registros integer,
  declarada_en timestamp DEFAULT now(),
  PRIMARY KEY (id),
  CONSTRAINT uq_jornada_caja UNIQUE (caja_modulo, fecha, colaborador),
  CONSTRAINT jornada_caja_resultado CHECK (resultado IN ('TERMINADA', 'CONTINUA'))
);

CREATE INDEX IF NOT EXISTS idx_jornada_caja_caja ON jornada_caja (caja_modulo);

CREATE TABLE IF NOT EXISTS asignacion_tecnica (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  modulo_id integer NOT NULL,
  usuario_id integer NOT NULL,
  PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS asignacion_tecnica_modulo_id ON asignacion_tecnica (modulo_id);
CREATE INDEX IF NOT EXISTS asignacion_tecnica_usuario_id ON asignacion_tecnica (usuario_id);

CREATE TABLE IF NOT EXISTS auditoria (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  entidad varchar(100) NOT NULL,
  entidad_id varchar(100),
  accion varchar(30) NOT NULL,
  detalle varchar(500),
  usuario varchar(150),
  fecha timestamp DEFAULT now() NOT NULL,
  PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS auditoria_idx_auditoria_entidad ON auditoria (entidad, entidad_id);
CREATE INDEX IF NOT EXISTS auditoria_idx_auditoria_fecha ON auditoria (fecha);

CREATE TABLE IF NOT EXISTS fuiddatosreal (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  fecha_del_dato date,
  n_orden integer,
  codigo varchar(255),
  entidad_remitente varchar(255),
  entidad_productora varchar(255),
  unidad_administrativa varchar(255),
  oficina_productora varchar(255),
  objeto varchar(255),
  serie varchar(255),
  subserie varchar(255),
  numero_de_orden_interno varchar(255),
  accionado_procesado varchar(255),
  accionado_denunciante varchar(255),
  identificacion varchar(255),
  asunto varchar(255),
  radicado varchar(255),
  numero_doc varchar(255),
  numero_doc_hasta varchar(255),
  fecha_inicial date,
  fecha_final date,
  caja varchar(255),
  upd varchar(255),
  tomo varchar(255),
  otro varchar(255),
  caja_interna varchar(255),
  folios varchar(255),
  soporte varchar(255),
  frecuencia varchar(255),
  elaborado_por varchar(255),
  nro_acta_transferible varchar(255),
  fecha_transferencia date,
  notas varchar(255),
  sede varchar(255),
  tiempo time,
  historial_y_cambios text,
  cambio_calidad varchar(255),
  sede_calidad varchar(255),
  asunto_2 varchar(255),
  asunto_3 varchar(255),
  created_at timestamp DEFAULT now(),
  updated_at timestamp DEFAULT now(),
  version integer DEFAULT 1 NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT unique_upd UNIQUE (upd)
);

CREATE INDEX IF NOT EXISTS fuiddatosreal_idx_fuid_acta ON fuiddatosreal (nro_acta_transferible);
CREATE INDEX IF NOT EXISTS fuiddatosreal_idx_fuid_elaborado_por ON fuiddatosreal (elaborado_por);
CREATE INDEX IF NOT EXISTS fuiddatosreal_idx_fuid_estado_revision ON fuiddatosreal (historial_y_cambios);
CREATE INDEX IF NOT EXISTS fuiddatosreal_idx_fuid_fecha_dato ON fuiddatosreal (fecha_del_dato);
CREATE INDEX IF NOT EXISTS fuiddatosreal_idx_fuid_sede ON fuiddatosreal (sede);
CREATE INDEX IF NOT EXISTS fuiddatosreal_idx_fuiddatosreal_caja ON fuiddatosreal (caja);

