CREATE INDEX IF NOT EXISTS modulos_caja_id_modulo_caja ON modulos_caja (id_modulo_caja);
CREATE INDEX IF NOT EXISTS modulos_caja_idx_modulos_caja_caja_modulo ON modulos_caja (caja_modulo);
