);

CREATE INDEX IF NOT EXISTS moduloscliente_fk_submodulo ON moduloscliente (id_submodulo);
CREATE INDEX IF NOT EXISTS moduloscliente_idx_moduloscliente_codigo ON moduloscliente (codigo);
CREATE INDEX IF NOT EXISTS moduloscliente_idx_moduloscliente_submodulo ON moduloscliente (id_submodulo);

CREATE TABLE IF NOT EXISTS rangos_upd (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  usuario_id integer NOT NULL,
  sub_modulo_id integer NOT NULL,
  upd_inicio varchar(10) NOT NULL,
  upd_fin varchar(10) NOT NULL,
  estado varchar(8) DEFAULT 'activo' NOT NULL CHECK (estado IN ('activo', 'agotado', 'revocado')),
  asignado_por integer NOT NULL,
  fecha_asignacion timestamp DEFAULT now() NOT NULL,
  fecha_agotado timestamp,
  fecha_revocacion timestamp,
  PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS rangos_upd_idx_rangos_asignado_por ON rangos_upd (asignado_por);
CREATE INDEX IF NOT EXISTS rangos_upd_idx_rangos_usuario_sub ON rangos_upd (usuario_id, sub_modulo_id, estado);

CREATE TABLE IF NOT EXISTS sub_modulos (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  codigo varchar(255) NOT NULL,
  entidad_remitente varchar(255) NOT NULL,
  sede_submodulos varchar(255),
  PRIMARY KEY (id)
);


-- El código de un cliente es único dentro de su sede: es lo que identifica al
-- cliente en el número de caja y en los reportes, y dos iguales en la misma
-- sede mezclarían sus cajas sin forma de separarlas. Entre sedes sí se repite.
CREATE UNIQUE INDEX IF NOT EXISTS uq_sub_modulos_codigo_sede
  ON sub_modulos (codigo, sede_submodulos);

CREATE TABLE IF NOT EXISTS users (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  cc varchar(50) NOT NULL,
  nombre varchar(100) NOT NULL,
  contrasena varchar(60),
  rol varchar(50) NOT NULL,
  sede varchar(255),
  suspendido_hasta date,
  created_at timestamp DEFAULT now(),
  updated_at timestamp DEFAULT now(),
  PRIMARY KEY (id)
);

-- Llaves foráneas
ALTER TABLE asignacion_caja_tecnica ADD CONSTRAINT asignacion_caja_tecnica_ibfk_1 FOREIGN KEY (modulo_id) REFERENCES modulos_caja (id) ON DELETE CASCADE;
ALTER TABLE asignacion_caja_tecnica ADD CONSTRAINT asignacion_caja_tecnica_ibfk_2 FOREIGN KEY (usuario_id) REFERENCES users (id) ON DELETE CASCADE;
ALTER TABLE asignacion_tecnica ADD CONSTRAINT asignacion_tecnica_ibfk_1 FOREIGN KEY (modulo_id) REFERENCES sub_modulos (id) ON DELETE CASCADE;
ALTER TABLE asignacion_tecnica ADD CONSTRAINT asignacion_tecnica_ibfk_2 FOREIGN KEY (usuario_id) REFERENCES users (id) ON DELETE CASCADE;
ALTER TABLE modulo_tecnica ADD CONSTRAINT modulo_tecnica_ibfk_1 FOREIGN KEY (modulo_id) REFERENCES moduloscliente (id) ON DELETE CASCADE;
ALTER TABLE modulo_tecnica ADD CONSTRAINT modulo_tecnica_ibfk_2 FOREIGN KEY (usuario_id) REFERENCES users (id) ON DELETE CASCADE;
ALTER TABLE modulos_caja ADD CONSTRAINT modulos_caja_ibfk_1 FOREIGN KEY (id_modulo_caja) REFERENCES moduloscliente (id);
ALTER TABLE moduloscliente ADD CONSTRAINT fk_submodulo FOREIGN KEY (id_submodulo) REFERENCES sub_modulos (id);

-- Equivalente de ON UPDATE CURRENT_TIMESTAMP.
CREATE OR REPLACE FUNCTION tocar_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS fuiddatosreal_updated_at ON fuiddatosreal;
CREATE TRIGGER fuiddatosreal_updated_at BEFORE UPDATE ON fuiddatosreal
  FOR EACH ROW EXECUTE FUNCTION tocar_updated_at();

DROP TRIGGER IF EXISTS modulos_caja_updated_at ON modulos_caja;
CREATE TRIGGER modulos_caja_updated_at BEFORE UPDATE ON modulos_caja
  FOR EACH ROW EXECUTE FUNCTION tocar_updated_at();

DROP TRIGGER IF EXISTS moduloscliente_updated_at ON moduloscliente;
CREATE TRIGGER moduloscliente_updated_at BEFORE UPDATE ON moduloscliente
  FOR EACH ROW EXECUTE FUNCTION tocar_updated_at();

DROP TRIGGER IF EXISTS users_updated_at ON users;
CREATE TRIGGER users_updated_at BEFORE UPDATE ON users
  FOR EACH ROW EXECUTE FUNCTION tocar_updated_at();
